"""ChannelPool: concat(max over channels, mean over channels) along dim 1."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'ChannelPool_12902',
    'batch': 16,
    'channels': 128,
    'height': 128,
    'width': 128,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype=dtype,
    )
    return (x,)


def workload(x):
    mx = jnp.max(x, axis=1, keepdims=True)
    mean = jnp.mean(x, axis=1, keepdims=True)
    return jnp.concatenate((mx, mean), axis=1)

"""[bf16 variant] ReLU followed by global L2 (Frobenius) norm: L2PenaltyConstraintLoss."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'L2PenaltyConstraintLoss_11013',
    'batch': 16,
    'channels': 128,
    'height': 128,
    'width': 256,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    shape = (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width'])
    x = jax.random.uniform(key, shape, dtype=dtype)
    return (x,)


def workload(x):
    gap_constraint = jax.nn.relu(x)
    return jnp.sqrt(jnp.sum(jnp.square(gap_constraint)))

"""PixelwiseNorm: x / sqrt(sum(x**2, dim=1, keepdim=True) + eps) over channels (NCHW)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'PixelwiseNorm_1129',
    'batch': 8,
    'channels': 128,
    'height': 256,
    'width': 256,
    'eps': 1e-07,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype,
    )
    return (x,)


def workload(x):
    return x / jnp.sqrt(jnp.sum(x ** 2, axis=1, keepdims=True) + CONFIG['eps'])

"""RSoftmax: view(B, groups, radix, -1) -> transpose(1, 2) -> softmax over radix -> reshape(B, -1) (sigmoid if radix == 1)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'RSoftmax_11171',
    'batch': 32,
    'channels': 512,
    'height': 64,
    'width': 64,
    'radix': 4,
    'groups': 1,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype=dtype,
    )
    return (x,)


def workload(x):
    radix = CONFIG['radix']
    groups = CONFIG['groups']
    batch = x.shape[0]
    if radix > 1:
        y = x.reshape(batch, groups, radix, -1)
        y = jnp.transpose(y, (0, 2, 1, 3))
        y = jax.nn.softmax(y, axis=1)
        return y.reshape(batch, -1)
    return jax.nn.sigmoid(x)
